[data-screen-root] {
  --c-bg: #17122A;
  --c-surface: #221E36;
  --c-surface-card: #282340;
  --c-text: #F6F2F0;
  --c-muted: #9E96A8;
  --c-border: #3A3252;
  --c-accent: #A855F7;
  --c-on-accent: #FFFFFF;
  --c-gold: #FACC15;

  --font-body: "Roboto", system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --fs-xs: 11px;
  --fs-sm: 13px;
  --fs-md: 15px;
  --fs-lg: 18px;
  --fs-xl: 26px;

  --r-sm: 8px;
  --r-md: 12px;
  --r-lg: 20px;

  font-family: var(--font-body);
  background-color: var(--c-bg);
  color: var(--c-text);
  font-size: var(--fs-md);
  box-sizing: border-box;
  -webkit-font-smoothing: antialiased;
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

[data-screen-root] * {
  box-sizing: border-box;
}

[data-screen-root] .app-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px;
  background: var(--c-bg);
  color: var(--c-text);
  font-size: var(--fs-lg);
  font-weight: 600;
}

[data-screen-root] .tab-bar {
  display: flex;
  align-items: center;
  justify-content: space-around;
  background: var(--c-surface);
  border-top: 1px solid var(--c-border);
  height: 64px;
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding-bottom: 12px;
}

[data-screen-root] .tab {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: var(--c-muted);
  font-size: var(--fs-xs);
  background: none;
  border: none;
  cursor: pointer;
  flex: 1;
  height: 100%;
}

[data-screen-root] .tab.is-selected {
  color: var(--c-accent);
}

[data-screen-root] .btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 20px;
  font-size: var(--fs-md);
  font-weight: 500;
  border-radius: var(--r-md);
  border: none;
  cursor: pointer;
  text-align: center;
  transition: opacity 0.2s;
}

[data-screen-root] .btn-primary {
  background: var(--c-accent);
  color: var(--c-on-accent);
  width: 100%;
}

[data-screen-root] .btn-secondary {
  background: transparent;
  color: var(--c-text);
  border: 1px solid var(--c-border);
}

[data-screen-root] .chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  font-size: var(--fs-sm);
  background: var(--c-surface);
  color: var(--c-text);
  border: 1px solid var(--c-border);
  border-radius: var(--r-lg);
  white-space: nowrap;
}

[data-screen-root] .counter,
[data-screen-root] .badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 8px;
  font-size: var(--fs-xs);
  font-weight: 600;
  border-radius: var(--r-sm);
  background: var(--c-surface);
  color: var(--c-text);
}

[data-screen-root] .badge {
  background: rgba(168, 85, 247, 0.2);
  color: var(--c-accent);
}

[data-screen-root] .card {
  background: var(--c-surface-card);
  border: 1px solid var(--c-border);
  border-radius: var(--r-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

[data-screen-root] .list-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  background: transparent;
  color: var(--c-text);
  font-size: var(--fs-md);
  border-bottom: 1px solid var(--c-border);
  cursor: pointer;
}

[data-screen-root] .list-row:last-child {
  border-bottom: none;
}

[data-screen-root] .bubble-in {
  background: var(--c-surface);
  color: var(--c-text);
  padding: 10px 14px;
  border-radius: var(--r-md) var(--r-md) var(--r-md) 2px;
  max-width: 80%;
  font-size: var(--fs-md);
}

[data-screen-root] .bubble-out {
  background: var(--c-accent);
  color: var(--c-on-accent);
  padding: 10px 14px;
  border-radius: var(--r-md) var(--r-md) 2px var(--r-md);
  max-width: 80%;
  font-size: var(--fs-md);
  align-self: flex-end;
}

[data-screen-root] .composer {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px;
  background: var(--c-surface);
  border-top: 1px solid var(--c-border);
}

[data-screen-root] .scrim {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.7);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
}

[data-screen-root] .modal,
[data-screen-root] .paywall {
  background: linear-gradient(135deg, #1A1730 0%, #0F0D1F 100%);
  border: 1px solid var(--c-border);
  border-radius: var(--r-lg);
  padding: 24px;
  width: 90%;
  max-width: 380px;
  color: var(--c-text);
  position: relative;
}

[data-screen-root] .sheet {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--c-surface);
  border-top-left-radius: var(--r-lg);
  border-top-right-radius: var(--r-lg);
  padding: 24px;
  border-top: 1px solid var(--c-border);
}

[data-screen-root] .store-tile {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: var(--r-md);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
